const updateTeam = `-- name: UpdateTeam :exec
UPDATE teams
SET name = $1, slug = $2, description = $3, own_working_hours = $4,
    working_days = $5::text[], working_start = $6::text,
    working_end = $7::text, working_time_zone = $8::text,
    updated_at = $9, version = version + 1
WHERE org_id = $10 AND id = $11
`

type UpdateTeamParams struct {
	Name            string
	Slug            string
	Description     string
	OwnWorkingHours bool
	WorkingDays     []string
	WorkingStart    pgtype.Text
	WorkingEnd      pgtype.Text
	WorkingTimeZone pgtype.Text
	Now             time.Time
	OrgID           int64
	ID              int64
}

// UpdateTeam replaces the configured fields of a Team and bumps its version.
func (q *Queries) UpdateTeam(ctx context.Context, arg UpdateTeamParams) error {
	_, err := q.db.Exec(ctx, updateTeam,
		arg.Name,
		arg.Slug,
		arg.Description,
		arg.OwnWorkingHours,
		arg.WorkingDays,
		arg.WorkingStart,
		arg.WorkingEnd,
		arg.WorkingTimeZone,
		arg.Now,
		arg.OrgID,
		arg.ID,
	)
	return err
}
